import urllib.request, urllib.parse, json, pathlib, time, threading
TOKEN=pathlib.Path('/config/Library/Application Support/Plex Media Server/.LocalAdminToken').read_text().strip()
def ask(path, method='GET', params={}):
 req=urllib.request.Request('http://127.0.0.1:32400'+path+'?'+urllib.parse.urlencode(params),method=method,headers={'X-Plex-Token':TOKEN,'Accept':'application/json'})
 with urllib.request.urlopen(req,timeout=30) as r:
  raw=r.read(); return json.loads(raw) if raw else {}
frames=[]
r=urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:32400/:/eventsource/notifications?filters=activity',headers={'X-Plex-Token':TOKEN,'Accept':'text/event-stream'}),timeout=60)
def reader():
 try:
  for line in r:
   text=line.decode().strip()
   if text.startswith('data:'):
    try: frames.append(json.loads(text[5:]))
    except ValueError: pass
 except Exception: pass
threading.Thread(target=reader,daemon=True).start()
print('analyze_response',ask('/library/metadata/1/analyze','PUT'))
time.sleep(15)
notes=[f for f in frames if 'ActivityNotification' in f]
pathlib.Path('/capture/analysis-failure-pms-raw.json').write_text(json.dumps(notes,indent=2)+'\n')
print(json.dumps(notes,indent=2))
